from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from typing import Optional

app = FastAPI()

@app.post("/submit")
async def submit(age: Optional[int] = Form(None)):
    return {"age": age}

client = TestClient(app)

def test_empty_string_form_value():
    # age is Optional[int], default is None.
    # If we send age="", it should be interpreted as None.
    response = client.post("/submit", data={"age": ""})
    print(f"Response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"age": None}

if __name__ == "__main__":
    try:
        test_empty_string_form_value()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()

